INSERT INTO academy_lesson(id,draft_json,published_json) VALUES ('setup','{"id": "setup", "title": "Prepara tu negocio y tu equipo", "category": "Configuración", "roles": ["OWNER"], "permission": null, "minutes": 3, "summary": "Revisa los datos de tu negocio y sus sedes en Configuración.", "steps": ["Revisa los datos de tu negocio y sus sedes en Configuración.", "Registra los servicios con su precio y duración antes de ofrecer citas.", "Configura profesionales, horarios y permisos de cada administrador. Comprueba cada acceso con su propia cuenta."], "videoUrl": null, "captionUrl": null, "videoPublicId": null, "sortOrder": 1}','{"id": "setup", "title": "Prepara tu negocio y tu equipo", "category": "Configuración", "roles": ["OWNER"], "permission": null, "minutes": 3, "summary": "Revisa los datos de tu negocio y sus sedes en Configuración.", "steps": ["Revisa los datos de tu negocio y sus sedes en Configuración.", "Registra los servicios con su precio y duración antes de ofrecer citas.", "Configura profesionales, horarios y permisos de cada administrador. Comprueba cada acceso con su propia cuenta."], "videoUrl": null, "captionUrl": null, "videoPublicId": null, "sortOrder": 1}') ON CONFLICT (id) DO NOTHING;
INSERT INTO academy_lesson(id,draft_json,published_json) VALUES ('sale','{"id": "sale", "title": "Registra una venta", "category": "Caja", "roles": ["OWNER", "ADMIN", "CASHIER"], "permission": "CASH_ACCESS", "minutes": 3, "summary": "Abre Caja, confirma la sede y selecciona Nueva venta.", "steps": ["Abre Caja, confirma la sede y selecciona Nueva venta.", "Busca al cliente por nombre o WhatsApp. Si no existe, completa sus datos para registrarlo.", "Selecciona servicios o productos, el profesional y las cantidades. Revisa el total y el medio de pago antes de cobrar y guardar."], "videoUrl": null, "captionUrl": null, "videoPublicId": null, "sortOrder": 2}','{"id": "sale", "title": "Registra una venta", "category": "Caja", "roles": ["OWNER", "ADMIN", "CASHIER"], "permission": "CASH_ACCESS", "minutes": 3, "summary": "Abre Caja, confirma la sede y selecciona Nueva venta.", "steps": ["Abre Caja, confirma la sede y selecciona Nueva venta.", "Busca al cliente por nombre o WhatsApp. Si no existe, completa sus datos para registrarlo.", "Selecciona servicios o productos, el profesional y las cantidades. Revisa el total y el medio de pago antes de cobrar y guardar."], "videoUrl": null, "captionUrl": null, "videoPublicId": null, "sortOrder": 2}') ON CONFLICT (id) DO NOTHING;
INSERT INTO academy_lesson(id,draft_json,published_json) VALUES ('close','{"id": "close", "title": "Revisa y cierra la caja", "category": "Caja", "roles": ["OWNER", "ADMIN", "CASHIER"], "permission": "CASH_ACCESS", "minutes": 3, "summary": "Confirma que estás trabajando con la caja y la sede correctas.", "steps": ["Confirma que estás trabajando con la caja y la sede correctas.", "Revisa ventas, ingresos y egresos. Compara el efectivo contado con lo registrado y explica cualquier diferencia.", "Verifica los importes antes de confirmar el cierre. Consulta el historial para revisar el resultado."], "videoUrl": null, "captionUrl": null, "videoPublicId": null, "sortOrder": 3}','{"id": "close", "title": "Revisa y cierra la caja", "category": "Caja", "roles": ["OWNER", "ADMIN", "CASHIER"], "permission": "CASH_ACCESS", "minutes": 3, "summary": "Confirma que estás trabajando con la caja y la sede correctas.", "steps": ["Confirma que estás trabajando con la caja y la sede correctas.", "Revisa ventas, ingresos y egresos. Compara el efectivo contado con lo registrado y explica cualquier diferencia.", "Verifica los importes antes de confirmar el cierre. Consulta el historial para revisar el resultado."], "videoUrl": null, "captionUrl": null, "videoPublicId": null, "sortOrder": 3}') ON CONFLICT (id) DO NOTHING;
INSERT INTO academy_lesson(id,draft_json,published_json) VALUES ('agenda','{"id": "agenda", "title": "Organiza las citas", "category": "Agenda", "roles": ["OWNER", "ADMIN"], "permission": "AGENDA_ACCESS", "minutes": 3, "summary": "Entra en Agenda y selecciona la fecha y la sede.", "steps": ["Entra en Agenda y selecciona la fecha y la sede.", "Elige al cliente, servicio y profesional. Revisa la disponibilidad y los datos antes de guardar.", "Cuando cambie una cita, revisa su estado y horario para evitar reservas duplicadas."], "videoUrl": null, "captionUrl": null, "videoPublicId": null, "sortOrder": 4}','{"id": "agenda", "title": "Organiza las citas", "category": "Agenda", "roles": ["OWNER", "ADMIN"], "permission": "AGENDA_ACCESS", "minutes": 3, "summary": "Entra en Agenda y selecciona la fecha y la sede.", "steps": ["Entra en Agenda y selecciona la fecha y la sede.", "Elige al cliente, servicio y profesional. Revisa la disponibilidad y los datos antes de guardar.", "Cuando cambie una cita, revisa su estado y horario para evitar reservas duplicadas."], "videoUrl": null, "captionUrl": null, "videoPublicId": null, "sortOrder": 4}') ON CONFLICT (id) DO NOTHING;
INSERT INTO academy_lesson(id,draft_json,published_json) VALUES ('customers','{"id": "customers", "title": "Edita clientes respetando su privacidad", "category": "Clientes", "roles": ["OWNER", "ADMIN"], "permission": "CUSTOMERS_ACCESS", "minutes": 3, "summary": "Busca al cliente y abre su ficha para consultar los datos disponibles.", "steps": ["Busca al cliente y abre su ficha para consultar los datos disponibles.", "Usa Editar para corregir nombre y apellido. Si aparece Teléfono oculto, guarda sin intentar reconstruir ni cambiar ese número.", "Revisa la ficha guardada. Eliminar retira al cliente de la lista activa: confirma siempre que elegiste a la persona correcta."], "videoUrl": null, "captionUrl": null, "videoPublicId": null, "sortOrder": 5}','{"id": "customers", "title": "Edita clientes respetando su privacidad", "category": "Clientes", "roles": ["OWNER", "ADMIN"], "permission": "CUSTOMERS_ACCESS", "minutes": 3, "summary": "Busca al cliente y abre su ficha para consultar los datos disponibles.", "steps": ["Busca al cliente y abre su ficha para consultar los datos disponibles.", "Usa Editar para corregir nombre y apellido. Si aparece Teléfono oculto, guarda sin intentar reconstruir ni cambiar ese número.", "Revisa la ficha guardada. Eliminar retira al cliente de la lista activa: confirma siempre que elegiste a la persona correcta."], "videoUrl": null, "captionUrl": null, "videoPublicId": null, "sortOrder": 5}') ON CONFLICT (id) DO NOTHING;
INSERT INTO academy_lesson(id,draft_json,published_json) VALUES ('reports','{"id": "reports", "title": "Interpreta tus reportes", "category": "Reportes", "roles": ["OWNER", "ADMIN"], "permission": "REPORTS_ACCESS", "minutes": 3, "summary": "Selecciona la sede y el intervalo de fechas antes de comparar resultados.", "steps": ["Selecciona la sede y el intervalo de fechas antes de comparar resultados.", "Revisa ventas, gastos y utilidad: los ingresos no equivalen a la ganancia del negocio.", "Compara periodos equivalentes y verifica los movimientos de caja cuando detectes diferencias."], "videoUrl": null, "captionUrl": null, "videoPublicId": null, "sortOrder": 6}','{"id": "reports", "title": "Interpreta tus reportes", "category": "Reportes", "roles": ["OWNER", "ADMIN"], "permission": "REPORTS_ACCESS", "minutes": 3, "summary": "Selecciona la sede y el intervalo de fechas antes de comparar resultados.", "steps": ["Selecciona la sede y el intervalo de fechas antes de comparar resultados.", "Revisa ventas, gastos y utilidad: los ingresos no equivalen a la ganancia del negocio.", "Compara periodos equivalentes y verifica los movimientos de caja cuando detectes diferencias."], "videoUrl": null, "captionUrl": null, "videoPublicId": null, "sortOrder": 6}') ON CONFLICT (id) DO NOTHING;
INSERT INTO academy_lesson(id,draft_json,published_json) VALUES ('client-access','{"id": "client-access", "title": "Crea tu acceso como cliente", "category": "Mi cuenta", "roles": ["CLIENT"], "permission": null, "minutes": 3, "summary": "En la pantalla de acceso del cliente, busca la opción para crear tu acceso si todavía no tienes contraseña.", "steps": ["En la pantalla de acceso del cliente, busca la opción para crear tu acceso si todavía no tienes contraseña.", "Ingresa tu número con el país correcto y completa los datos que solicite la app.", "Sigue la verificación que aparezca. Si ya tienes cuenta, inicia sesión o utiliza la recuperación de contraseña. No compartas códigos de acceso."], "videoUrl": null, "captionUrl": null, "videoPublicId": null, "sortOrder": 7}','{"id": "client-access", "title": "Crea tu acceso como cliente", "category": "Mi cuenta", "roles": ["CLIENT"], "permission": null, "minutes": 3, "summary": "En la pantalla de acceso del cliente, busca la opción para crear tu acceso si todavía no tienes contraseña.", "steps": ["En la pantalla de acceso del cliente, busca la opción para crear tu acceso si todavía no tienes contraseña.", "Ingresa tu número con el país correcto y completa los datos que solicite la app.", "Sigue la verificación que aparezca. Si ya tienes cuenta, inicia sesión o utiliza la recuperación de contraseña. No compartas códigos de acceso."], "videoUrl": null, "captionUrl": null, "videoPublicId": null, "sortOrder": 7}') ON CONFLICT (id) DO NOTHING;
INSERT INTO academy_lesson(id,draft_json,published_json) VALUES ('client-booking','{"id": "client-booking", "title": "Reserva tu próxima visita", "category": "Reservas", "roles": ["CLIENT"], "permission": null, "minutes": 3, "summary": "Entra al negocio donde deseas atenderte y abre la opción de reservar.", "steps": ["Entra al negocio donde deseas atenderte y abre la opción de reservar.", "Selecciona el servicio, profesional y horario disponible. Revisa la sede antes de confirmar.", "Consulta tus reservas para comprobar la confirmación. Las opciones de cambio dependen del estado de la cita y las reglas del negocio."], "videoUrl": null, "captionUrl": null, "videoPublicId": null, "sortOrder": 8}','{"id": "client-booking", "title": "Reserva tu próxima visita", "category": "Reservas", "roles": ["CLIENT"], "permission": null, "minutes": 3, "summary": "Entra al negocio donde deseas atenderte y abre la opción de reservar.", "steps": ["Entra al negocio donde deseas atenderte y abre la opción de reservar.", "Selecciona el servicio, profesional y horario disponible. Revisa la sede antes de confirmar.", "Consulta tus reservas para comprobar la confirmación. Las opciones de cambio dependen del estado de la cita y las reglas del negocio."], "videoUrl": null, "captionUrl": null, "videoPublicId": null, "sortOrder": 8}') ON CONFLICT (id) DO NOTHING;
INSERT INTO academy_lesson(id,draft_json,published_json) VALUES ('client-points','{"id": "client-points", "title": "Consulta tus puntos y premios", "category": "Beneficios", "roles": ["CLIENT"], "permission": null, "minutes": 3, "summary": "Abre la sección de puntos o beneficios dentro del negocio.", "steps": ["Abre la sección de puntos o beneficios dentro del negocio.", "Revisa tu saldo y las condiciones de cada premio: pueden variar entre negocios.", "Consulta cómo canjear el premio disponible antes de usarlo. Tu historial permite revisar las visitas registradas."], "videoUrl": null, "captionUrl": null, "videoPublicId": null, "sortOrder": 9}','{"id": "client-points", "title": "Consulta tus puntos y premios", "category": "Beneficios", "roles": ["CLIENT"], "permission": null, "minutes": 3, "summary": "Abre la sección de puntos o beneficios dentro del negocio.", "steps": ["Abre la sección de puntos o beneficios dentro del negocio.", "Revisa tu saldo y las condiciones de cada premio: pueden variar entre negocios.", "Consulta cómo canjear el premio disponible antes de usarlo. Tu historial permite revisar las visitas registradas."], "videoUrl": null, "captionUrl": null, "videoPublicId": null, "sortOrder": 9}') ON CONFLICT (id) DO NOTHING;
INSERT INTO academy_lesson(id,draft_json,published_json) VALUES ('barber-day','{"id": "barber-day", "title": "Prepara tu jornada", "category": "Mi trabajo", "roles": ["BARBER"], "permission": null, "minutes": 3, "summary": "Entra con tu cuenta de profesional y confirma el negocio en el encabezado.", "steps": ["Entra con tu cuenta de profesional y confirma el negocio en el encabezado.", "Consulta tus citas y revisa horarios, servicios y clientes asignados.", "Ante un cambio o cruce de horarios, coordina con la administración antes de modificar la atención."], "videoUrl": null, "captionUrl": null, "videoPublicId": null, "sortOrder": 10}','{"id": "barber-day", "title": "Prepara tu jornada", "category": "Mi trabajo", "roles": ["BARBER"], "permission": null, "minutes": 3, "summary": "Entra con tu cuenta de profesional y confirma el negocio en el encabezado.", "steps": ["Entra con tu cuenta de profesional y confirma el negocio en el encabezado.", "Consulta tus citas y revisa horarios, servicios y clientes asignados.", "Ante un cambio o cruce de horarios, coordina con la administración antes de modificar la atención."], "videoUrl": null, "captionUrl": null, "videoPublicId": null, "sortOrder": 10}') ON CONFLICT (id) DO NOTHING;
INSERT INTO academy_lesson(id,draft_json,published_json) VALUES ('barber-attend','{"id": "barber-attend", "title": "Registra la atención de un cliente", "category": "Atención", "roles": ["BARBER"], "permission": null, "minutes": 3, "summary": "Abre la atención correspondiente al cliente o la cita asignada.", "steps": ["Abre la atención correspondiente al cliente o la cita asignada.", "Revisa los servicios realizados y los datos antes de finalizar. No registres servicios que no se brindaron.", "Confirma el resultado y revisa el historial. Si el cobro lo gestiona caja, coordina para evitar duplicar la venta."], "videoUrl": null, "captionUrl": null, "videoPublicId": null, "sortOrder": 11}','{"id": "barber-attend", "title": "Registra la atención de un cliente", "category": "Atención", "roles": ["BARBER"], "permission": null, "minutes": 3, "summary": "Abre la atención correspondiente al cliente o la cita asignada.", "steps": ["Abre la atención correspondiente al cliente o la cita asignada.", "Revisa los servicios realizados y los datos antes de finalizar. No registres servicios que no se brindaron.", "Confirma el resultado y revisa el historial. Si el cobro lo gestiona caja, coordina para evitar duplicar la venta."], "videoUrl": null, "captionUrl": null, "videoPublicId": null, "sortOrder": 11}') ON CONFLICT (id) DO NOTHING;
